#include <vector>
#include <cmath>
#include <algorithm>

class Solution {
public:
    int minSwaps(std::vector<int>& nums) {
        std::vector<int> evens, odds;
        for (int i = 0; i < (int)nums.size(); ++i) {
            if (nums[i] % 2 == 0) evens.push_back(i);
            else odds.push_back(i);
        }

        if (std::abs((int)evens.size() - (int)odds.size()) > 1) return -1;

        auto calc_swaps = [](const std::vector<int>& indices, int start) {
            long long total = 0;
            for (int i = 0; i < (int)indices.size(); ++i) {
                total += std::abs(indices[i] - (start + 2 * i));
            }
            return (int)total;
        };

        if (evens.size() > odds.size()) return calc_swaps(evens, 0);
        if (odds.size() > evens.size()) return calc_swaps(odds, 0);
        return std::min(calc_swaps(evens, 0), calc_swaps(evens, 1));
    }
};

import java.util.*;

class Solution {
    public int minSwaps(int[] nums) {
        List<Integer> evens = new ArrayList<>();
        List<Integer> odds = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] % 2 == 0) evens.add(i);
            else odds.add(i);
        }

        if (Math.abs(evens.size() - odds.size()) > 1) return -1;

        if (evens.size() > odds.size()) return calcSwaps(evens, 0);
        if (odds.size() > evens.size()) return calcSwaps(odds, 0);
        return Math.min(calcSwaps(evens, 0), calcSwaps(evens, 1));
    }

    private int calcSwaps(List<Integer> indices, int start) {
        int total = 0;
        for (int i = 0; i < indices.size(); i++) {
            total += Math.abs(indices.get(i) - (start + 2 * i));
        }
        return total;
    }
}

